 * // RecordProvider will be wrapped with NotificationsProvider only if
 * // NotificationsContext is not already in the tree
 * const RecordProviderWithNotifications = withContextIfNotWrapped(
 * RecordProvider,
 * NotificationsContext,
 * NotificationsProvider
 * );
 *
 * // Usage 1: NotificationsProvider not in tree - will wrap
 * <RecordProviderWithNotifications table="incident" sysId="123">
 * <MyComponent />
 * </RecordProviderWithNotifications>
 *
 * // Usage 2: NotificationsProvider already in tree - won't wrap
 * <NotificationsProvider>
 * <RecordProviderWithNotifications table="incident" sysId="123">
 * <MyComponent />
